# Loader for the frozen independent augmented observation-correction reference
# (accepted private reference: nine fixtures on 36 original F identities, four
# stored irregular dates, four explicit links and three deduplicated OR blocks;
# see manifest.json and extract_fixture.py for provenance). Owners are REAL
# sealed cdid owners built from the accepted atoms through locked namespace
# constructors. Every expected value is read from the accepted tables; nothing
# here is generated by the backend under test.

aug_fixture_specs <- data.frame(
  fixture_id = c("pair_sep_jsep", "pair_within_jwithin", "pair_across_jacross", "date_sep_jwithin",
    "date_within_jacross", "date_across_jsep", "pair_intercept_only", "pair_retained_alias",
    "pair_V_across_jwithin"),
  selection_model = c("pair_logit", "pair_logit", "pair_logit", "independent_period_logit",
    "independent_period_logit", "independent_period_logit", "pair_logit", "pair_logit", "pair_logit"),
  selection_pooling = c("separate", "within_cohort", "across_cohorts", "separate", "within_cohort",
    "across_cohorts", "across_cohorts", "separate", "across_cohorts"),
  imputation_pooling = c("separate", "within_cohort", "across_cohorts", "within_cohort", "across_cohorts",
    "separate", "within_cohort", "separate", "within_cohort"),
  recipe = c("intercept", "no_intercept", "intercept", "intercept", "no_intercept", "intercept",
    "intercept_only", "retained_alias", "intercept"),
  selection_slope = c("x2", "x2", "x2", "x2", "x2", "x2", "none", "x2", "V"),
  source = c(rep("main", 8L), "selection_only_v"),
  stringsAsFactors = FALSE
)

aug_dates <- c(2000, 2002, 2005, 2010)
aug_pairs <- list(e12 = c(1L, 2L), e23 = c(2L, 3L), e13 = c(1L, 3L))
aug_reference_cohorts <- c(0, 2005, 2010)
# Reference links (target g, control pool K, pair) in the accepted order.
aug_links <- list(
  list(g = 2005, K = 0, pair = "e12"),
  list(g = 2010, K = 0, pair = "e12"),
  list(g = 2005, K = c(0, 2010), pair = "e23"),
  list(g = 2005, K = c(0, 2010), pair = "e13")
)

# Byte pins of every copied/derived table (manifest.csv; the same pins are in
# manifest.json together with the accepted source hashes and extraction rule).
aug_fixture_verify_hashes <- function(dir, expected_files = 16L) {
  man <- utils::read.csv(file.path(dir, "manifest.csv"), stringsAsFactors = FALSE,
    colClasses = c("character", "numeric", "character", "character"))
  stopifnot(nrow(man) == expected_files, !anyDuplicated(man$file))
  sha <- if (exists("sha256sum", envir = asNamespace("tools"), inherits = FALSE))
    get("sha256sum", envir = asNamespace("tools")) else NULL
  for (i in seq_len(nrow(man))) {
    path <- file.path(dir, man$file[i])
    stopifnot(file.exists(path), file.size(path) == man$bytes[i],
      identical(unname(tools::md5sum(path)), man$md5[i]))
    if (!is.null(sha)) stopifnot(identical(unname(sha(path)), man$sha256[i]))
  }
  invisible(nrow(man))
}

aug_cache <- new.env(parent = emptyenv())

aug_table <- function(dir, sub, name) {
  key <- paste(sub, name, sep = "/")
  if (is.null(aug_cache[[key]])) {
    aug_cache[[key]] <- utils::read.csv(file.path(dir, sub, name), stringsAsFactors = FALSE)
  }
  aug_cache[[key]]
}

# Expected values of one fixture, read only from the accepted tables.
aug_expectations <- function(dir, spec, ids) {
  sub <- spec$source
  fid <- spec$fixture_id
  vals <- aug_table(dir, sub, "values.csv")
  vals <- vals[vals$fixture == fid, , drop = FALSE]
  uif <- aug_table(dir, sub, "unit_if_analytic.csv")
  uif <- uif[uif$fixture == fid, , drop = FALSE]
  comps <- aug_table(dir, sub, "components.csv")
  comps <- comps[comps$fixture == fid, , drop = FALSE]
  covs <- aug_table(dir, sub, "covariance.csv")
  covs <- covs[covs$fixture == fid, , drop = FALSE]
  preds <- aug_table(dir, sub, "predictions.csv")
  preds <- preds[preds$fixture == fid, , drop = FALSE]
  proj <- aug_table(dir, sub, "projection.csv")
  proj <- proj[proj$fixture == fid, , drop = FALSE]
  proj_if <- aug_table(dir, sub, "projection_if.csv")
  proj_if <- proj_if[proj_if$fixture == fid, , drop = FALSE]
  stopifnot(nrow(vals) > 0L, nrow(uif) > 0L, nrow(comps) == 4L * length(ids))
  value <- function(coord) {
    v <- vals$value[match(coord, vals$coordinate)]
    if (anyNA(v)) stop("Reference coordinate absent: ", paste(coord[is.na(v)], collapse = ", "))
    v
  }
  if_row <- function(coord) {
    r <- uif[uif$coordinate == coord, , drop = FALSE]
    if (nrow(r) != length(ids)) stop("Reference IF rows absent for ", coord)
    r$analytic[match(ids, r$unit_id)]
  }
  component <- function(link, field) {
    r <- comps[comps$link == link, , drop = FALSE]
    r[[field]][match(ids, r$unit_id)]
  }
  list(values = vals, value = value, if_row = if_row, component = component,
    has = function(coord) coord %in% vals$coordinate,
    coordinates = vals$coordinate, covariance = covs, predictions = preds,
    projection = proj, projection_if = proj_if)
}

load_augmented_finite_reference <- function(dir, fixture_id, order = NULL, max_chunk_rows = 13L,
                                            ns = asNamespace("cdid")) {
  spec <- aug_fixture_specs[aug_fixture_specs$fixture_id == fixture_id, , drop = FALSE]
  stopifnot(nrow(spec) == 1L)
  fn <- function(name) {
    stopifnot(isNamespace(ns), environmentIsLocked(ns), bindingIsLocked(name, ns))
    get(name, envir = ns, inherits = FALSE)
  }
  atoms <- aug_table(dir, "main", "atoms.csv")
  N <- nrow(atoms)
  ids0 <- as.numeric(atoms$unit_id)
  V0 <- ((5 * atoms$unit_id) %% 11 - 5) / 5
  if (identical(spec$source, "selection_only_v")) {
    va <- aug_table(dir, "selection_only_v", "atoms.csv")
    stopifnot(identical(as.numeric(va$unit_id), ids0), max(abs(va$V - V0)) == 0,
      max(abs(va$w - atoms$w)) == 0)
  }
  g0 <- ifelse(atoms$cohort == 0, Inf, as.numeric(atoms$cohort))
  R0 <- as.matrix(atoms[paste0("R_", aug_dates)])
  storage.mode(R0) <- "double"
  D0 <- lapply(names(aug_pairs), function(e) as.numeric(atoms[[paste0("Delta_", e)]]))
  names(D0) <- names(aug_pairs)
  for (e in names(aug_pairs)) {
    pr <- aug_pairs[[e]]
    stopifnot(identical(!is.na(D0[[e]]), R0[, pr[1L]] * R0[, pr[2L]] == 1))
  }

  # Outcome levels consistent with the observed pair changes (base 0 at the
  # first observed date); exact pair changes are supplied separately through
  # the private `pair_outcomes` fixture hook because the 8-decimal atoms are
  # not exactly additive in five units.
  Y0 <- matrix(NA_real_, N, 4L)
  for (i in seq_len(N)) {
    r <- R0[i, ]
    if (r[1L]) Y0[i, 1L] <- 0
    if (r[2L]) Y0[i, 2L] <- if (r[1L]) D0$e12[i] else 0
    if (r[3L]) Y0[i, 3L] <- if (r[2L]) Y0[i, 2L] + D0$e23[i] else if (r[1L]) D0$e13[i] else 0
    if (r[4L]) Y0[i, 4L] <- 0
  }
  long <- data.frame(id = rep(ids0, each = 4L), time = rep(aug_dates, N), y = as.vector(t(Y0)),
    g = rep(g0, each = 4L))
  zero <- which(rowSums(R0) == 0)
  long <- long[!long$id %in% ids0[zero[-1L]], , drop = FALSE]
  rownames(long) <- NULL

  ctrl <- fn("ipw_owner_control")(max_chunk_rows = max_chunk_rows, max_retained_entries = 1e8,
    max_matrix_entries = 2e8, max_work_ops = 1e13, max_output_entries = 1e8)
  panel <- fn("construct_ipw_panel_owner")(long, "id", "time", "y", "g", ctrl)
  ord <- if (is.null(order)) seq_len(N) else order
  stopifnot(length(ord) == N, setequal(ord, seq_len(N)))

  x1 <- atoms$x1
  x2 <- atoms$x2
  X <- switch(spec$recipe,
    intercept = cbind(`(Intercept)` = 1, x1 = x1, x2 = x2),
    no_intercept = cbind(x1 = x1, x2 = x2),
    intercept_only = cbind(`(Intercept)` = rep(1, N)),
    retained_alias = cbind(`(Intercept)` = 1, x1 = x1, x2 = x2, x1_twice = 2 * x1, x1_plus_x2 = x1 + x2))
  intercept <- spec$recipe != "no_intercept"
  slopes <- setdiff(colnames(X), "(Intercept)")
  q_intercept <- spec$recipe != "no_intercept"
  Q <- switch(spec$selection_slope, x2 = cbind(x2 = x2), V = cbind(V = V0), none = matrix(0, N, 0L))
  if (q_intercept) Q <- cbind(`(Intercept)` = 1, Q)
  frame <- fn("construct_ipw_frame_owner")(panel, ids0[ord], X[ord, , drop = FALSE],
    weights = atoms$w[ord], control = ctrl, frame_g = g0[ord], allow_frame_only = TRUE,
    design_on_A_only = TRUE)
  reader <- fn("construct_cp04_frame_reader")(frame, ids0[ord], Q[ord, , drop = FALSE], g0[ord],
    atoms$w[ord], ctrl, has_intercept = q_intercept)
  views <- lapply(seq_along(aug_links), function(l) {
    lk <- aug_links[[l]]
    pr <- aug_pairs[[lk$pair]]
    fn("construct_ipw_link_view")(frame, aug_dates[pr[1L]], aug_dates[pr[2L]],
      g = lk$g, K = ifelse(lk$K == 0, Inf, lk$K), control = ctrl, link_id = paste0("l", l),
      functional_key = paste0("cmpcat:augmented-reference:", fixture_id, ":l", l))
  })
  pair_outcomes <- lapply(names(aug_pairs), function(e) D0[[e]][ord])
  names(pair_outcomes) <- vapply(aug_pairs, function(pr) paste0(aug_dates[pr[1L]], ":", aug_dates[pr[2L]]),
    character(1L))
  pair_outcomes_from_levels <- lapply(aug_pairs, function(pr) (Y0[, pr[2L]] - Y0[, pr[1L]])[ord])
  names(pair_outcomes_from_levels) <- names(pair_outcomes)
  recipe <- fn("or_pooled_outcome_recipe")(colnames(X), intercept, slopes)
  list(
    spec = spec,
    N = N,
    ids = ids0[ord],
    order = ord,
    g = g0[ord],
    w = atoms$w[ord],
    cluster = atoms$cluster_id[ord],
    A = as.double(rowSums(R0) >= 2)[ord],
    x = cbind(x1 = x1, x2 = x2)[ord, , drop = FALSE],
    V = V0[ord],
    Delta = lapply(D0, function(d) d[ord]),
    panel = panel,
    frame = frame,
    reader = reader,
    views = views,
    X_frame = X[ord, , drop = FALSE],
    pair_outcomes = pair_outcomes,
    pair_outcomes_from_levels = pair_outcomes_from_levels,
    outcome_recipe = recipe,
    treatment_columns = if (identical(spec$recipe, "retained_alias")) c("(Intercept)", "x1", "x2") else colnames(X),
    control = ctrl,
    glm_control = list(epsilon = 1e-15, maxit = 60L, trace = FALSE),
    rank_tol = fn("or_public_rank_tol")(),
    expectations = aug_expectations(dir, spec, ids0[ord])
  )
}
